/* GENERATED FILE — do not edit. Source: spec/. Run: pnpm gen */

@layer components {
  .ew-avatar {
    /* anatomy: root, image, fallback, presence */
  }
  .ew-avatar {
    position: relative;
    display: inline-grid; place-items: center; overflow: visible;
    width: 40px; height: 40px;
    border-radius: var(--ew-structure-control-radius, 999px);
    background: var(--ew-color-bg-surface); color: var(--ew-color-fg-default);
    border: var(--ew-structure-card-border-width, 1px) solid var(--ew-color-border-subtle);
    font-family: var(--ew-font-body, system-ui, sans-serif); font-weight: 700; font-size: 14px;
  }
  .ew-avatar[data-variant="square"] { border-radius: var(--ew-structure-surface-radius, 8px); }
  .ew-avatar[data-size="sm"] { width: 32px; height: 32px; font-size: 12px; }
  .ew-avatar[data-size="lg"] { width: 56px; height: 56px; font-size: 16px; }
  .ew-avatar__image { width: 100%; height: 100%; object-fit: cover; }
  .ew-avatar__fallback { line-height: 1; }
  .ew-avatar__presence {
    position: absolute; right: 0; bottom: 0; width: 10px; height: 10px;
    border: 2px solid var(--ew-color-bg-surface); box-sizing: border-box;
  }
  .ew-avatar__presence[data-presence="online"] { background: var(--ew-color-action-bg); border-radius: 999px; }
  .ew-avatar__presence[data-presence="away"] { background: transparent; border-radius: 999px; box-shadow: inset 0 0 0 2px var(--ew-color-action-bg); }
  .ew-avatar__presence[data-presence="busy"] { background: var(--ew-color-danger-bg); border-radius: 2px; }
  .ew-avatar__presence[data-presence="offline"] { background: transparent; border-radius: 999px; box-shadow: inset 0 0 0 2px var(--ew-color-fg-muted); }
  .ew-avatar-group { display: flex; padding-inline-start: 8px; }
  .ew-avatar-group .ew-avatar { margin-inline-start: -8px; }
  /* spec variant variant=circle */
  .ew-avatar[data-variant="circle"] { --ew-spec-variant-variant: circle; }
  /* spec variant variant=square */
  .ew-avatar[data-variant="square"] { --ew-spec-variant-variant: square; }
  .ew-avatar:not([data-variant]) { --ew-spec-variant-variant: circle; }
  .ew-avatar[data-size="sm"] { --ew-spec-size: sm; }
  .ew-avatar[data-size="md"] { --ew-spec-size: md; }
  .ew-avatar[data-size="lg"] { --ew-spec-size: lg; }
  .ew-avatar:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-avatar, .ew-avatar *, .ew-avatar *::before, .ew-avatar *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
